sealed class BindingException: kotlin.Exception() {

    class Runtime(

        val `code`: RuntimeErrorCode,

        val `message`: kotlin.String,

        val `recoveryBound`: RecoveryBound?
        ) : BindingException() {
        override val message
            get() = "code=${ `code` }, message=${ `message` }, recoveryBound=${ `recoveryBound` }"
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BindingException> {
        override fun lift(error_buf: RustBuffer.ByValue): BindingException = FfiConverterTypeBindingError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeBindingError : FfiConverterRustBuffer<BindingException> {
    override fun read(buf: ByteBuffer): BindingException {


        return when(buf.getInt()) {
            1 -> BindingException.Runtime(
                FfiConverterTypeRuntimeErrorCode.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalTypeRecoveryBound.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BindingException): ULong {
        return when(value) {
            is BindingException.Runtime -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeRuntimeErrorCode.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`message`)
                + FfiConverterOptionalTypeRecoveryBound.allocationSize(value.`recoveryBound`)
            )
        }
    }

    override fun write(value: BindingException, buf: ByteBuffer) {
        when(value) {
            is BindingException.Runtime -> {
                buf.putInt(1)
                FfiConverterTypeRuntimeErrorCode.write(value.`code`, buf)
                FfiConverterString.write(value.`message`, buf)
                FfiConverterOptionalTypeRecoveryBound.write(value.`recoveryBound`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




